SELECT 'core-2026-09-v4','linking-clauses','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"linking-clauses","title":"Linking clauses: time, reason, purpose and result","level":"B1","order":45,"summary":"Connect ideas with the right kind of clause or phrase, and keep their logical relationship clear.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Coordinating complete ideas","Reasons: because and because of","Purpose and result","Time clauses and sequence"],"rules":[{"title":"Coordinating complete ideas","explanation":"And, but and or can connect words, phrases or clauses of equal status. When linking two independent clauses, punctuation helps mark the boundary. Choose the connector from the intended relation: addition, contrast or alternative.","pattern":"We checked the route, **and** we booked the tickets.","commonMistakes":["A connector should express the intended relation; grammatical sentences can still communicate the wrong logic."],"examples":["“We were tired **because** we had prepared the visitor guide all morning.”","“We were tired **because** we had restored the old portrait all morning.”"],"skill":"form"},{"title":"Reasons: because and because of","explanation":"Because introduces a finite clause with a subject and verb. Because of introduces a noun phrase or an -ing expression. The meaning may be similar, but the grammar following the connector differs.","pattern":"**Because it rained**, we stayed. / **Because of the rain**, we stayed.","commonMistakes":["Because of it rained puts a finite clause after a preposition phrase without the structure needed for it."],"examples":["“We could not prepare the visitor guide **because of** the power cut.”","“We could not restore the old portrait **because of** the power cut.”"],"skill":"meaning"},{"title":"Purpose and result","explanation":"A to-infinitive often gives purpose when its understood subject matches the main subject. So that can introduce a finite purpose clause, especially when the subjects differ. So and therefore can introduce results, but therefore behaves as an adverb and needs suitable sentence punctuation.","pattern":"I spoke slowly **so that everyone could follow**.","commonMistakes":["Therefore cannot always replace so between two clauses with the same punctuation; avoid a comma splice."],"examples":["Express purpose with a different subject: “I brought the instructions **so that** you could prepare the visitor guide.”","Express purpose with a different subject: “I brought the instructions **so that** you could restore the old portrait.”"],"skill":"contrast"},{"title":"Time clauses and sequence","explanation":"When, while, before, after, until and as soon as describe different temporal relations. While often accompanies an activity in progress; until describes continuation up to a point. In an ordinary future time clause, use a present form rather than will.","pattern":"I’ll wait **until you arrive**.","commonMistakes":["By Friday gives a deadline; until Friday says something continues to Friday. They are not interchangeable."],"examples":["Use the time preposition before an -ing noun phrase: “The error occurred during the process of **preparing** the visitor guide.”","Use the time preposition before an -ing noun phrase: “The error occurred during the process of **restoring** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Connect ideas with the right kind of clause or phrase, and keep their logical relationship clear.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Coordinating complete ideas","explanation":"And, but and or can connect words, phrases or clauses of equal status. When linking two independent clauses, punctuation helps mark the boundary. Choose the connector from the intended relation: addition, contrast or alternative.","pattern":"We checked the route, **and** we booked the tickets.","commonMistakes":["A connector should express the intended relation; grammatical sentences can still communicate the wrong logic."],"examples":["“We were tired **because** we had prepared the visitor guide all morning.”","“We were tired **because** we had restored the old portrait all morning.”"],"skill":"form","id":"linking-clauses-foundation-1","domain":"adjuncts","referenceIds":["dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Reasons: because and because of","explanation":"Because introduces a finite clause with a subject and verb. Because of introduces a noun phrase or an -ing expression. The meaning may be similar, but the grammar following the connector differs.","pattern":"**Because it rained**, we stayed. / **Because of the rain**, we stayed.","commonMistakes":["Because of it rained puts a finite clause after a preposition phrase without the structure needed for it."],"examples":["“We could not prepare the visitor guide **because of** the power cut.”","“We could not restore the old portrait **because of** the power cut.”"],"skill":"meaning","id":"linking-clauses-foundation-2","domain":"adjuncts","referenceIds":["dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Purpose and result","explanation":"A to-infinitive often gives purpose when its understood subject matches the main subject. So that can introduce a finite purpose clause, especially when the subjects differ. So and therefore can introduce results, but therefore behaves as an adverb and needs suitable sentence punctuation.","pattern":"I spoke slowly **so that everyone could follow**.","commonMistakes":["Therefore cannot always replace so between two clauses with the same punctuation; avoid a comma splice."],"examples":["Express purpose with a different subject: “I brought the instructions **so that** you could prepare the visitor guide.”","Express purpose with a different subject: “I brought the instructions **so that** you could restore the old portrait.”"],"skill":"contrast","id":"linking-clauses-foundation-3","domain":"adjuncts","referenceIds":["dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"title":"Time clauses and sequence","explanation":"When, while, before, after, until and as soon as describe different temporal relations. While often accompanies an activity in progress; until describes continuation up to a point. In an ordinary future time clause, use a present form rather than will.","pattern":"I’ll wait **until you arrive**.","commonMistakes":["By Friday gives a deadline; until Friday says something continues to Friday. They are not interchangeable."],"examples":["Use the time preposition before an -ing noun phrase: “The error occurred during the process of **preparing** the visitor guide.”","Use the time preposition before an -ing noun phrase: “The error occurred during the process of **restoring** the old portrait.”"],"skill":"application","id":"linking-clauses-foundation-4","domain":"adjuncts","referenceIds":["dfe-grammar"],"readingVersion":"core-2026-09-v3"},{"domain":"coordination","id":"coordination-and-parallelism","title":"Coordinating words, phrases and clauses","explanation":"And, or and but can join units at different levels: words, phrases or clauses. Coordinated units normally perform compatible grammatical jobs. Parallel wording makes a list easier to interpret, especially when units share an opening verb or preposition. The relationship may be addition, an alternative or a contrast.","pattern":"reading **and** writing · on Monday **or** on Tuesday","examples":["The room was **small but comfortable**.","She wants **to study, to travel and to work abroad**."],"commonMistakes":["A conjunction does not repair an incompatible shared pattern: interested in music and to paint should be rephrased as interested in music and painting."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"coordination","id":"correlative-coordination","title":"Both…and, either…or, neither…nor","explanation":"Paired coordinators mark how two alternatives or parts belong together. Place the paired words before corresponding grammatical units. With neither…nor, the coordination already has negative meaning. Agreement with alternatives of different persons or numbers can sound awkward; a plural reformulation often gives the clearest result.","pattern":"**both** the book **and** the film","examples":["You can **either stay here or come with us**.","She is **not only a musician but also a teacher**."],"commonMistakes":["Not only at the beginning of a clause can trigger inversion: Not only did she sing, but she also played. In the middle of a noun phrase, it does not."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"coordination","id":"shared-material-coordination","title":"Sharing and omitting repeated material","explanation":"Coordinated phrases and clauses can share grammatical material when the missing part is recoverable. The scope of a shared modifier can be ambiguous, so repeat it when necessary. In formal writing, make it clear whether a description applies to both parts or only the nearest one.","pattern":"Leo ordered tea and Mia **[ordered]** coffee.","examples":["She **opened and read** the letter.","We invited **the teachers and the students**."],"commonMistakes":["Old men and women can describe two groups in different ways. If age applies to both, write old men and old women when clarity matters."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"adjuncts","id":"adjunct-types-and-position","title":"Manner, means, accompaniment, viewpoint and stance","explanation":"Adjuncts can locate an event or describe how, by what means, with whom, from what viewpoint or with what attitude it is presented. Some attach closely to a verb phrase; others comment on the whole clause. Front position often frames the message, while end position commonly adds new circumstances.","pattern":"**By train**, **with a friend**, **in my opinion**","examples":["She solved it **by checking the figures**.","**Fortunately**, nobody was hurt."],"commonMistakes":["An adverb after a linking verb may not do the job of a subject adjective: she looks happy describes her appearance; she looks happily at the photo describes her action."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"adjuncts","id":"time-clause-relations","title":"Before, after, until, by the time, once and whenever","explanation":"Time clauses locate one event relative to another. Until marks continuation to an endpoint; by the time identifies a reference point by which something is true or complete. Once marks a condition becoming satisfied; whenever marks any or every relevant occasion. Ordinary future time clauses normally use a present form.","pattern":"Wait **until** I arrive. / Finish **by the time** I arrive.","examples":["**Once you have paid**, we will send the ticket.","She calls **whenever she needs advice**."],"commonMistakes":["Future reference does not require will inside every subordinate clause: I’ll call when I arrive. An embedded question is different: I don’t know when she will arrive."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["We checked the route, **and** we booked the tickets.","**Because it rained**, we stayed. / **Because of the rain**, we stayed.","I spoke slowly **so that everyone could follow**.","I’ll wait **until you arrive**."],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["wishes"],"readingReferenceIds":["dfe-grammar","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='linking-clauses'
